SELECT json_build_object('source', source, 'class', class, 'part', part, 'rows', rows, 'ids', ids) FROM (
SELECT 'observations.selected_sporely_taxon_id' AS source, 'live_dependency' AS class, r.part, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observations t JOIN retired r ON t.selected_sporely_taxon_id = r.retired GROUP BY r.part
UNION ALL
SELECT 'observations.resolved_sporely_taxon_id' AS source, 'live_dependency' AS class, r.part, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observations t JOIN retired r ON t.resolved_sporely_taxon_id = r.retired GROUP BY r.part
UNION ALL
SELECT 'observations.taxon_identity(sporely ns)' AS source, 'live_dependency' AS class, r.part, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observations t JOIN retired r ON t.taxon_identity_namespace = 'sporely_taxon_id' AND t.taxon_identity_external_id = r.retired::text GROUP BY r.part
UNION ALL
SELECT 'observations.taxon_identity(nortaxa tuple; resolution changes, incl. NULL selected/resolved)' AS source, 'live_dependency' AS class, r.part, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observations t JOIN retired r ON t.taxon_identity_source_system = 'nortaxa' AND t.taxon_identity_namespace = 'nortaxa_taxon_id' AND t.taxon_identity_external_id = r.nortaxa_id GROUP BY r.part
UNION ALL
SELECT 'observation_reference_uses(via observation)' AS source, 'live_dependency' AS class, r.part, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observation_reference_uses u JOIN public.observations t ON t.id = u.observation_id JOIN retired r ON r.retired IN (t.selected_sporely_taxon_id, t.resolved_sporely_taxon_id) GROUP BY r.part
UNION ALL
SELECT 'taxonomy_v3.resolution_link.resolved_sporely_taxon_id' AS source, 'live_dependency' AS class, r.part, count(*) AS rows, count(DISTINCT r.retired) AS ids
