SELECT json_build_object('source', source, 'class', class, 'expected', expected, 'rows', rows, 'ids', ids) FROM (
SELECT 'S1.observations.selected_sporely_taxon_id' AS source, 'live_dependency' AS class, '0 (snapshot verified 0)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observations t JOIN s1 r ON t.selected_sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.observations.resolved_sporely_taxon_id' AS source, 'live_dependency' AS class, '0 (snapshot verified 0)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observations t JOIN s1 r ON t.resolved_sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.observations.taxon_identity(sporely ns)' AS source, 'live_dependency' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observations t JOIN s1 r ON t.taxon_identity_namespace = 'sporely_taxon_id' AND t.taxon_identity_external_id = r.retired::text
UNION ALL
SELECT 'S1.observations.taxon_identity(nortaxa accepted id)' AS source, 'live_dependency' AS class, '>=1 (desktop mirror shows 1 external_unresolved on 55146, unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observations t JOIN s1_nt n ON n.kind = 'accepted' AND t.taxon_identity_source_system = 'nortaxa' AND t.taxon_identity_namespace = 'nortaxa_taxon_id' AND t.taxon_identity_external_id = n.nortaxa_id JOIN s1 r ON r.retired = n.retired
UNION ALL
SELECT 'S1.observations.taxon_identity(nortaxa synonym id)' AS source, 'live_dependency' AS class, 'unverified' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observations t JOIN s1_nt n ON n.kind = 'synonym' AND t.taxon_identity_source_system = 'nortaxa' AND t.taxon_identity_namespace = 'nortaxa_taxon_id' AND t.taxon_identity_external_id = n.nortaxa_id JOIN s1 r ON r.retired = n.retired
UNION ALL
SELECT 'S1.observations.taxon_identity(nortaxa S1 tuple) with a selected id' AS source, 'live_dependency' AS class, '0 (unverified): external_unresolved rows carry no selection' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observations t JOIN s1_nt n ON t.taxon_identity_source_system = 'nortaxa' AND t.taxon_identity_namespace = 'nortaxa_taxon_id' AND t.taxon_identity_external_id = n.nortaxa_id AND t.selected_sporely_taxon_id IS NOT NULL JOIN s1 r ON r.retired = n.retired
UNION ALL
SELECT 'S1.observations.ai_selected_taxon_id(NBIC provider id)' AS source, 'live_dependency' AS class, 'unverified (desktop: 21 NBIC ids, all accepted ids)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observations t JOIN s1_nt n ON t.ai_selected_taxon_id IN (n.nortaxa_id, 'NBIC:' || n.nortaxa_id) JOIN s1 r ON r.retired = n.retired
UNION ALL
SELECT 'S1.observation_identifications.top_taxon_id(legacy, id space unverified)' AS source, 'live_dependency' AS class, 'unverified' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observation_identifications t JOIN s1_nt n ON t.top_taxon_id IN (n.nortaxa_id, 'NBIC:' || n.nortaxa_id) JOIN s1 r ON r.retired = n.retired
UNION ALL
SELECT 'S1.observation_reference_uses(via observation)' AS source, 'live_dependency' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observation_reference_uses u JOIN public.observations t ON t.id = u.observation_id JOIN s1 r ON r.retired IN (t.selected_sporely_taxon_id, t.resolved_sporely_taxon_id)
UNION ALL
SELECT 'S1.taxonomy_v3.resolution_link.resolved_sporely_taxon_id' AS source, 'live_dependency' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM taxonomy_v3.resolution_link t JOIN s1 r ON t.resolved_sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.public.reference_taxon_treatments.taxon_id(text)' AS source, 'live_dependency' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.reference_taxon_treatments t JOIN s1 r ON t.taxon_id = r.retired::text
UNION ALL
SELECT 'S1.public.reference_curated_forks.sporely_taxon_id' AS source, 'live_dependency' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.reference_curated_forks t JOIN s1 r ON t.sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.private.shared_reference_contributions.sporely_taxon_id' AS source, 'live_dependency' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM private.shared_reference_contributions t JOIN s1 r ON t.sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.private.curated_reference_treatment_taxa.sporely_taxon_id' AS source, 'live_dependency' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM private.curated_reference_treatment_taxa t JOIN s1 r ON t.sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.private.curated_reference_publication_taxa.sporely_taxon_id' AS source, 'live_dependency' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM private.curated_reference_publication_taxa t JOIN s1 r ON t.sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.public.observation_reference_uses.snapshot_json(taxon_id leaf)' AS source, 'historical_evidence' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.observation_reference_uses t JOIN s1 r ON t.snapshot_json::text ~ ('"(sporely_)?taxon_id"[[:space:]]*:[[:space:]]*"?' || r.retired::text || '([^0-9]|$)')
UNION ALL
SELECT 'S1.public.reference_curated_forks.source_envelope_json(taxon_id leaf)' AS source, 'historical_evidence' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.reference_curated_forks t JOIN s1 r ON t.source_envelope_json::text ~ ('"(sporely_)?taxon_id"[[:space:]]*:[[:space:]]*"?' || r.retired::text || '([^0-9]|$)')
UNION ALL
SELECT 'S1.private.curated_reference_publications.snapshot_json(taxon_id leaf)' AS source, 'historical_evidence' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM private.curated_reference_publications t JOIN s1 r ON t.snapshot_json::text ~ ('"(sporely_)?taxon_id"[[:space:]]*:[[:space:]]*"?' || r.retired::text || '([^0-9]|$)')
UNION ALL
SELECT 'S1.private.shared_reference_contribution_revisions.envelope_json(taxon_id leaf)' AS source, 'historical_evidence' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM private.shared_reference_contribution_revisions t JOIN s1 r ON t.envelope_json::text ~ ('"(sporely_)?taxon_id"[[:space:]]*:[[:space:]]*"?' || r.retired::text || '([^0-9]|$)')
UNION ALL
SELECT 'S1.private.reference_curation_submission_versions.candidate_json(taxon_id leaf)' AS source, 'historical_evidence' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM private.reference_curation_submission_versions t JOIN s1 r ON t.candidate_json::text ~ ('"(sporely_)?taxon_id"[[:space:]]*:[[:space:]]*"?' || r.retired::text || '([^0-9]|$)')
UNION ALL
SELECT 'S1.taxonomy_v3.identification_snapshot(original nortaxa tuple)' AS source, 'historical_evidence' AS class, 'unverified' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM taxonomy_v3.identification_snapshot t JOIN s1_nt n ON t.original_source_system = 'nortaxa' AND t.original_namespace = 'nortaxa_taxon_id' AND t.original_external_id = n.nortaxa_id JOIN s1 r ON r.retired = n.retired
UNION ALL
SELECT 'S1.taxonomy_v3.identification_snapshot.original_legacy_taxon_id(id space unverified)' AS source, 'historical_evidence' AS class, 'unverified' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM taxonomy_v3.identification_snapshot t JOIN s1_nt n ON t.original_legacy_taxon_id = n.nortaxa_id JOIN s1 r ON r.retired = n.retired
UNION ALL
SELECT 'S1.private.retired_resolution_repair_items(superseded or survivor)' AS source, 'historical_evidence' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM private.retired_resolution_repair_items t JOIN s1 r ON r.retired IN (t.superseded_sporely_taxon_id, t.survivor_sporely_taxon_id)
UNION ALL
SELECT 'S1.private.retired_resolution_repair_registry_additions.sporely_taxon_id' AS source, 'historical_evidence' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM private.retired_resolution_repair_registry_additions t JOIN s1 r ON t.sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.private.taxon_identity_repair_items.sporely_taxon_id' AS source, 'historical_evidence' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM private.taxon_identity_repair_items t JOIN s1 r ON t.sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.private.taxon_identity_repair_reference_actions(old or new)' AS source, 'historical_evidence' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM private.taxon_identity_repair_reference_actions t JOIN s1 r ON r.retired IN (t.old_sporely_taxon_id, t.new_sporely_taxon_id)
UNION ALL
SELECT 'S1.public.taxa.taxon_id(legacy table, id space unverified)' AS source, 'historical_evidence' AS class, 'unverified' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.taxa t JOIN s1 r ON t.taxon_id = r.retired
UNION ALL
SELECT 'S1.public.taxa_vernacular.taxon_id(legacy table, id space unverified)' AS source, 'historical_evidence' AS class, 'unverified' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.taxa_vernacular t JOIN s1 r ON t.taxon_id = r.retired
UNION ALL
SELECT 'S1.taxonomy_v3.registry_concept(retiree present)' AS source, 'registry_append_only' AS class, '988 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM taxonomy_v3.registry_concept t JOIN s1 r ON t.sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.taxonomy_v3.registry_concept(survivor present)' AS source, 'registry_append_only' AS class, '988 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM taxonomy_v3.registry_concept t JOIN s1 r ON t.sporely_taxon_id = r.survivor
UNION ALL
SELECT 'S1.taxonomy_v3.external_mapping(on retiree)' AS source, 'registry_append_only' AS class, 'unverified' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM taxonomy_v3.external_mapping t JOIN s1 r ON t.sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.taxonomy_v3.external_mapping(nortaxa S1 tuple -> other than retiree)' AS source, 'registry_append_only' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM taxonomy_v3.external_mapping t JOIN s1_nt n ON t.source_system = 'nortaxa' AND t.namespace = 'nortaxa_taxon_id' AND t.external_id = n.nortaxa_id JOIN s1 r ON r.retired = n.retired AND t.sporely_taxon_id <> r.retired
UNION ALL
SELECT 'S1.public.taxonomy_v2_concepts(retiree)' AS source, 'generated_release_row' AS class, '0: retirees are outside the cloud scope (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.taxonomy_v2_concepts t JOIN s1 r ON t.sporely_taxon_id = r.retired
UNION ALL
SELECT 'S1.public.taxonomy_v2_taxa(active, retiree or parent)' AS source, 'generated_release_row' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.taxonomy_v2_taxa t JOIN s1 r ON r.retired IN (t.sporely_taxon_id, t.parent_sporely_taxon_id) AND t.release_id = (SELECT release_id FROM public.taxonomy_v2_releases WHERE status = 'active')
UNION ALL
SELECT 'S1.public.taxonomy_v2_taxa(active, survivor present)' AS source, 'generated_release_row' AS class, '499 survivors in cloud scope (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.taxonomy_v2_taxa t JOIN s1 r ON t.sporely_taxon_id = r.survivor AND t.release_id = (SELECT release_id FROM public.taxonomy_v2_releases WHERE status = 'active')
UNION ALL
SELECT 'S1.public.taxonomy_v2_scientific_names(active, retiree)' AS source, 'generated_release_row' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.taxonomy_v2_scientific_names t JOIN s1 r ON t.sporely_taxon_id = r.retired AND t.release_id = (SELECT release_id FROM public.taxonomy_v2_releases WHERE status = 'active')
UNION ALL
SELECT 'S1.public.taxonomy_v2_vernacular_names(active, retiree)' AS source, 'generated_release_row' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.taxonomy_v2_vernacular_names t JOIN s1 r ON t.sporely_taxon_id = r.retired AND t.release_id = (SELECT release_id FROM public.taxonomy_v2_releases WHERE status = 'active')
UNION ALL
SELECT 'S1.public.taxonomy_v2_external_ids(active, retiree)' AS source, 'generated_release_row' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.taxonomy_v2_external_ids t JOIN s1 r ON t.sporely_taxon_id = r.retired AND t.release_id = (SELECT release_id FROM public.taxonomy_v2_releases WHERE status = 'active')
UNION ALL
SELECT 'S1.public.taxonomy_v2_external_ids(active, nortaxa tuple on S1 ids)' AS source, 'generated_release_row' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.taxonomy_v2_external_ids t JOIN s1_nt n ON t.source_system = 'nortaxa' AND t.namespace = 'nortaxa_taxon_id' AND t.external_id = n.nortaxa_id AND t.release_id = (SELECT release_id FROM public.taxonomy_v2_releases WHERE status = 'active') JOIN s1 r ON r.retired = n.retired
UNION ALL
SELECT 'S1.public.taxonomy_v2_legacy_external_ids(active, retiree)' AS source, 'generated_release_row' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.taxonomy_v2_legacy_external_ids t JOIN s1 r ON t.sporely_taxon_id = r.retired AND t.release_id = (SELECT release_id FROM public.taxonomy_v2_releases WHERE status = 'active')
UNION ALL
SELECT 'S1.public.taxonomy_v2_redlist(active, retiree)' AS source, 'generated_release_row' AS class, '0 (unverified)' AS expected, count(*) AS rows, count(DISTINCT r.retired) AS ids
  FROM public.taxonomy_v2_redlist t JOIN s1 r ON t.sporely_taxon_id = r.retired AND t.release_id = (SELECT release_id FROM public.taxonomy_v2_releases WHERE status = 'active')
) q;

-- S1 consistency gates (cloud side). Expected values are the 2026-10-20 snapshot; all unverified until run.
SELECT json_build_object('gate', 'CG0 active release', 'expected', 'tax-2026.10.07-01', 'value', (SELECT release_id FROM public.taxonomy_v2_releases WHERE status = 'active'));
SELECT json_build_object('gate', 'CG1 selected ids absent from the active release', 'expected', 0, 'value',
  (SELECT count(DISTINCT o.selected_sporely_taxon_id) FROM public.observations o WHERE o.selected_sporely_taxon_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.taxonomy_v2_taxa x WHERE x.sporely_taxon_id = o.selected_sporely_taxon_id AND x.release_id = (SELECT release_id FROM public.taxonomy_v2_releases WHERE status = 'active'))));
SELECT json_build_object('gate', 'CG2 resolved ids absent from the registry', 'expected', 0, 'value',
  (SELECT count(DISTINCT o.resolved_sporely_taxon_id) FROM public.observations o WHERE o.resolved_sporely_taxon_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM taxonomy_v3.registry_concept c WHERE c.sporely_taxon_id = o.resolved_sporely_taxon_id)));
SELECT json_build_object('gate', 'CG3 resolved ids outside the active release (drift check)', 'expected', '87 distinct at snapshot', 'value',
  (SELECT count(DISTINCT o.resolved_sporely_taxon_id) FROM public.observations o WHERE o.resolved_sporely_taxon_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.taxonomy_v2_taxa x WHERE x.sporely_taxon_id = o.resolved_sporely_taxon_id AND x.release_id = (SELECT release_id FROM public.taxonomy_v2_releases WHERE status = 'active'))));
SELECT json_build_object('gate', 'CG4 resolved ids 634896-634916 (absent from the desktop release)', 'expected', '20 ids, none is an S1 id', 'value',
  (SELECT json_agg(DISTINCT o.resolved_sporely_taxon_id) FROM public.observations o WHERE o.resolved_sporely_taxon_id BETWEEN 634896 AND 634916),
  'in_registry', (SELECT count(*) FROM taxonomy_v3.registry_concept c WHERE c.sporely_taxon_id BETWEEN 634896 AND 634916));
-- CG5b (template, run with the cloud ids printed by s1_desktop_gates.py --print-g4-cloud-ids, not embedded because
--   they identify the owner's rows): SELECT id, selected_sporely_taxon_id, taxon_identity_state
--   FROM public.observations WHERE id IN (<G4 cloud ids>)   expected: selected_sporely_taxon_id IS NULL
--   for every row, otherwise the desktop fallback push (identity_push.py:130-144) would clear it.
SELECT json_build_object('gate', 'CG5 inconsistent rows: external_unresolved state with a selected id', 'expected', 0, 'value',
  (SELECT count(*) FROM public.observations o WHERE o.taxon_identity_state = 'external_unresolved' AND o.selected_sporely_taxon_id IS NOT NULL));
ROLLBACK;
